// Cleanup to funkcja ZWRACANA z useEffect.
// React wywoła ją w dwóch sytuacjach:
//   1. Przed odmontowaniem komponentu (zniknie ze strony).
//   2. Przed kolejnym uruchomieniem efektu.

useEffect(() => {
  const id = setInterval(() => {
    console.log("tick");
  }, 1000);

  return () => clearInterval(id); // <-- cleanup zatrzymuje timer
}, []);

// BEZ cleanup: timer działa nawet po zniknięciu komponentu!
// Efekt: wycieki pamięci (memory leak).

// Zasada:
//   jeśli coś URUCHAMIASZ → w cleanup to ZATRZYMAJ.
//   Timer    → clearInterval / clearTimeout
//   Listener → removeEventListener
//   Fetch    → AbortController.abort()
